pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address sender, uint256 payAmount) public {
        vm.assume(sender != address(0));
        payAmount = bound(payAmount, 0, 1e27);

        vm.deal(sender, payAmount);
        vm.prank(sender);
        bool ok;
        try c.play{value: payAmount}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint pot = c.pot();

        assertTrue(pot % 10 == 0);
    }
}
